draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // character 1
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W/4 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W/4 + 30, H/2 + 70);
  ctx.stroke();

  // character 2
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 20);
  ctx.lineTo(W - W/4, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 50);
  ctx.lineTo(W - W/4 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 50);
  ctx.lineTo(W - W/4 + 30, H/2 + 70);
  ctx.stroke();

  // action
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + Math.sin(t) * 50, H/2 + 50);
  ctx.stroke();

  // book
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 - 20, H/2 - 50, 40, 10);
  ctx.fillStyle = 'white';
  ctx.font = '12px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('How to win', W/2, H/2 - 45);
  ctx.fillText('friends &', W/2, H/2 - 30);
  ctx.fillText('influence people', W/2, H/2 - 15);

  ctx.restore();
}
